# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TOHUMUN ÇİMLENMESİNE ETKİ EDEN FAKTÖRLER (SOS KURALI)</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">Çimlenme İçin Zorunlu (SOS)</text>\n  <text x="180" y="112" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">1. SU (Nem):</text>\n  <text x="180" y="130" text-anchor="middle" font-size="11" fill="#334155">Tohum kabuğunu çatlatır, enzimleri çalıştırır.</text>\n  <text x="180" y="158" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">2. OKSİJEN (Hava):</text>\n  <text x="180" y="176" text-anchor="middle" font-size="11" fill="#334155">Embriyonun solunum yapması için şarttır.</text>\n  <text x="180" y="204" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">3. SICAKLIK (Uygun):</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" fill="#334155">Çok soğuk veya çok sıcakta çimlenme olmaz.</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#b91c1c">Çimlenmede Gerekli OLMAYANLAR</text>\n  <text x="520" y="112" text-anchor="middle" font-size="12" fill="#7f1d1d">• IŞIK: Tohum henüz fotosentez yapmaz</text>\n  <text x="520" y="130" text-anchor="middle" font-size="11" fill="#475569">(Yaprağı yoktur, çenekten beslenir).</text>\n  <text x="520" y="158" text-anchor="middle" font-size="12" fill="#7f1d1d">• KARBONDİOKSİT: Fotosentez başladıktan</text>\n  <text x="520" y="176" text-anchor="middle" font-size="11" fill="#475569">sonra (genç bitki olunca) gerekir.</text>\n  <text x="520" y="204" text-anchor="middle" font-size="12" fill="#7f1d1d">• TOPRAK: Nemli pamukta da çimlenir;</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11" fill="#475569">toprak büyüme evresinde gereklidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KONTROLLÜ DENEYDE DEĞİŞKENLER VE HİPOTEZ KURMA (FB.6.3.3)</text>\n  <rect x="25" y="55" width="205" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="127" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Bağımsız Değişken</text>\n  <text x="127" y="105" text-anchor="middle" font-size="11" fill="#1e3a8a">Deneyde araştırmacının</text>\n  <text x="127" y="123" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">bilerek değiştirdiği</text>\n  <text x="127" y="141" text-anchor="middle" font-size="11" fill="#1e3a8a">etkendir (Neden).</text>\n  <text x="127" y="172" text-anchor="middle" font-size="11" fill="#475569">Örn: Bir kaba su koyup</text>\n  <text x="127" y="188" text-anchor="middle" font-size="11" fill="#475569">diğerini kuru bırakmak</text>\n  <text x="127" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">(Değişken: Su / Nem)</text>\n  <rect x="247" y="55" width="205" height="175" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Bağımlı Değişken</text>\n  <text x="350" y="105" text-anchor="middle" font-size="11" fill="#713f12">Bağımsız değişkene bağlı</text>\n  <text x="350" y="123" text-anchor="middle" font-size="11" font-weight="bold" fill="#713f12">olarak etkilenen</text>\n  <text x="350" y="141" text-anchor="middle" font-size="11" fill="#713f12">durumdur (Sonuç).</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11" fill="#475569">Örn: Tohumun çimlenip</text>\n  <text x="350" y="188" text-anchor="middle" font-size="11" fill="#475569">çimlenmemesi durumu</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">(Sonuç: Çimlenme durumu)</text>\n  <rect x="470" y="55" width="205" height="175" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="572" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Kontrol Edilen Değişken</text>\n  <text x="572" y="105" text-anchor="middle" font-size="11" fill="#581c87">Her iki düzenekte de</text>\n  <text x="572" y="123" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">sabit (aynı) tutulan</text>\n  <text x="572" y="141" text-anchor="middle" font-size="11" fill="#581c87">diğer tüm şartlardır.</text>\n  <text x="572" y="172" text-anchor="middle" font-size="11" fill="#475569">Örn: Tohum türü, sıcaklık</text>\n  <text x="572" y="188" text-anchor="middle" font-size="11" fill="#475569">(25°C) ve oksijen miktarı</text>\n  <text x="572" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#6d28d9">(Sabit Tutulanlar)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OMURGALI HAYVANLARDA ÜREME, BÜYÜME VE BAŞKALAŞIM (FB.6.3.4)</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="78" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Omurgalı Gruplarında Üreme ve Bakım</text>\n  <text x="180" y="104" text-anchor="middle" font-size="11" fill="#164e63">• Balıklar &amp; Kurbağalar: Yumurta ile ürer,</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#164e63">dış döllenme görülür, yavru bakımı yoktur.</text>\n  <text x="180" y="144" text-anchor="middle" font-size="11" fill="#164e63">• Sürüngenler: Yumurta, yavru bakımı yoktur.</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11" fill="#164e63">• Kuşlar: Yumurta, kuluçka ve yavru bakımı vardır.</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11" fill="#164e63">• Memeliler: Doğurarak ürer, yavrusunu</text>\n  <text x="180" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">sütle besler ve yavru bakımı görülür.</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="520" y="78" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Başkalaşım (Metamorfoz) Döngüleri</text>\n  <text x="520" y="106" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">Kurbağanın Hayat Döngüsü:</text>\n  <text x="520" y="126" text-anchor="middle" font-size="11" fill="#7c2d12">Yumurta → İribaş (Larva) → Genç → Ergin Kurbağa</text>\n  <text x="520" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">Kelebeğin (İpek Böceği) Döngüsü:</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11" fill="#7c2d12">Yumurta → Tırtıl (Larva) → Pupa (Koza) → Kelebek</text>\n  <text x="520" y="210" text-anchor="middle" font-size="11" fill="#475569">(Yumurta besini az olduğu için gelişim dışarıda sürer)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
